n=16
seen=set(); ties=[]
for i in range(n):
    for j in range(n):
        orb={(i,j),(i,n-1-j),(n-1-i,j),(n-1-i,n-1-j)}
        if orb<=seen: continue
        seen|=orb
        vals=[test[a][b] for a,b in orb]
        c=Counter(vals)
        if len(c)>1: ties.append((sorted(orb),vals,c))
